// refervo.com/share/biz?d=BASE64URL_PAYLOAD
//
// Public landing page for "My Biz" share links generated by the mobile app.
// The URL itself carries the entire card payload (name, phone, optional email
// and note) — there's no DB lookup, no analytics, no cookies. Just a
// stateless decode-and-render.
//
// The matching encoder/decoder lives in mobile (refervo-app) at
// src/utils/myBizShare.ts and is mirrored here in _shared.js (kept in sync
// by hand).
//
// Recipients on a device with the ReferVo app can tap "Add to My ReferVo" to
// deep-link straight into the import flow (handled in Phase 3c). Recipients
// without the app land on /get which routes them to the right store.

import { decodeMyBizShareUrl } from './_shared.js';

const DOWNLOAD_URL = 'https://refervo.com/get';

// ───────────────────────────────────────────────────────────────────
// Route entry
// ───────────────────────────────────────────────────────────────────
export async function onRequest(context) {
  const { request } = context;
  const url = new URL(request.url);
  const d = url.searchParams.get('d');

  const card = decodeMyBizShareUrl(d);

  if (!card) {
    return htmlResponse(renderInvalidShare(), 400);
  }

  return htmlResponse(renderShare({ card, rawD: d }), 200);
}

// ───────────────────────────────────────────────────────────────────
// Helpers
// ───────────────────────────────────────────────────────────────────

function escapeHtml(str) {
  if (str == null) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function formatPhone(phone) {
  const digits = String(phone || '').replace(/\D/g, '');
  if (digits.length === 10) {
    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
  }
  return String(phone || '');
}

