function headHtml(title, ogMeta = '') {
  return `
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
    <meta name="robots" content="noindex">
    <title>${escapeHtml(title)}</title>
    ${ogMeta}
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800&family=DM+Sans:wght@400;500;600&display=swap" rel="stylesheet">
    <style>${baseStyles()}</style>
  `;
}

// ───────────────────────────────────────────────────────────────────
// Templates
// ───────────────────────────────────────────────────────────────────

function renderShare({ card, rawD }) {
  const safeName  = escapeHtml(card.name);
  const safePhone = escapeHtml(formatPhone(card.phone));
  // tel: URIs use the raw digits, not the display-formatted version
  const telDigits = String(card.phone || '').replace(/\D/g, '');
  const safeTel   = escapeHtml(telDigits);
  const safeEmail = card.email ? escapeHtml(card.email) : null;
  const safeNote  = card.note ? escapeHtml(card.note) : null;

  // Preserve the d param exactly as received in the deep link so the app's
  // import handler decodes the same payload the landing page just rendered.
  const deepLink  = `refervo://share/biz?d=${encodeURIComponent(rawD)}`;

  const ogMeta = `
    <meta property="og:title" content="${safeName} on ReferVo">
    <meta property="og:description" content="Someone shared this business with you. Tap to add it to your network.">
    <meta property="og:type" content="website">
    <meta name="twitter:card" content="summary">
  `;

  return `<!DOCTYPE html>
<html lang="en">
<head>
  ${headHtml(`${card.name} on ReferVo`, ogMeta)}
</head>
<body>
  <div class="container">
    <div class="logo">
      <span class="logo-refer">Refer</span><span class="logo-vo">Vo</span>
    </div>

    <div class="card">
      <h1>Someone shared this business with you on ReferVo</h1>
      <p class="subtitle">Add them to your network so you can refer them and track who you trust.</p>

      <div class="biz-preview">
        <div class="biz-name">${safeName}</div>

        <div class="biz-meta-row">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.91.34 1.85.57 2.81.7A2 2 0 0 1 22 16.92z"/>
          </svg>
          <a href="tel:${safeTel}">${safePhone}</a>
        </div>

        ${safeEmail ? `
        <div class="biz-meta-row biz-email">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
            <polyline points="22,6 12,13 2,6"/>
          </svg>
          <a href="mailto:${safeEmail}">${safeEmail}</a>
        </div>
        ` : ''}

        ${safeNote ? `<div class="biz-note">${safeNote}</div>` : ''}
      </div>

      <a href="${deepLink}" class="cta-primary">
        Add to My ReferVo
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <line x1="5" y1="12" x2="19" y2="12"/>
          <polyline points="12 5 19 12 12 19"/>
        </svg>
      </a>

      <a href="${DOWNLOAD_URL}" class="cta-secondary">
        Don\u2019t have ReferVo? <strong>Get it \u2192</strong>
      </a>
    </div>

    <div class="footer">
      Powered by <a href="https://refervo.com">ReferVo</a>
    </div>
  </div>
</body>
</html>`;
}

function renderInvalidShare() {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  ${headHtml('This share link doesn\u2019t seem complete')}
</head>
<body>
  <div class="container">
    <div class="logo">
      <span class="logo-refer">Refer</span><span class="logo-vo">Vo</span>
    </div>
    <div class="card" style="text-align:center;">
      <h1>This share link doesn\u2019t seem complete</h1>
      <p class="subtitle">Ask the sender to share again. Links sometimes get truncated when copied across apps.</p>
      <a href="https://refervo.com" class="btn btn-primary" style="text-decoration:none;">Go to refervo.com</a>
    </div>
  </div>
</body>
</html>`;
}

function htmlResponse(html, status = 200) {
  return new Response(html, {
    status,
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'no-referrer-when-downgrade',
    },
  });
}
